#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Manual run of the phase 1 scenario on GitHub (issue #19, AC-5): one person
# with two clones on one machine plays Ana (the maintainer) and Ben (a second
# team member). You type every bfc command yourself in two terminal windows;
# the wizard shows each command, then checks the result read-only and writes
# a report for the pull request that closes #19. Run it from Git Bash, once
# main has .beforecode/config.yaml and bfc close (#49):
#
#   bash scripts/manual-e2e-github.sh
#
# Set BFC_E2E_DIR to use another work directory than ~/bfc-e2e-github. Each
# run writes its own report, result-<time>.md, there.

TOTAL_STAGES=11

REPO_URL="https://github.com/admSla99/BeforeCode.git"
REF="refs/beforecode/plans"
ANA_NAME="admSla99"
ANA_EMAIL="188631245+admSla99@users.noreply.github.com"
BEN_NAME="Ben Bitdiddle"
BEN_EMAIL="ben@example.com"
WORK="${BFC_E2E_DIR:-$HOME/bfc-e2e-github}"
ANA="$WORK/ana"
BEN="$WORK/ben"
STAMP=$(date +%Y%m%d-%H%M)
mkdir -p "$WORK"
# One report and one value file per run, so an earlier run's results and
# Short IDs never mix into this one.
LOG="$WORK/result-$STAMP.md"
ENV_FILE="$WORK/state-$STAMP.env"
PASSED=0
FAILED=0

# cmd "text" shows a command for the human to type.
cmd() { printf '      %s$ %s%s\n' "$BOLD" "$1" "$RESET"; }

# in_window NAME DIR says which terminal window the next commands go to.
in_window() { printf '\n  %sIn the %s window%s %s(%s)%s\n' "$BOLD" "$1" "$RESET" "$DIM" "$2" "$RESET"; }

log() { printf '%s\n' "$@" >> "$LOG"; }

# check "what" COMMAND...: runs a read-only check and records the result.
check() {
  local what="$1"; shift
  if "$@" >/dev/null 2>&1; then
    PASSED=$((PASSED + 1)); printf '  %s✓ %s%s\n' "$GREEN" "$what" "$RESET"; log "- [x] $what"
  else
    FAILED=$((FAILED + 1)); printf '  %s✗ %s%s\n' "$RED" "$what" "$RESET"; log "- [ ] $what **(failed)**"
  fi
}

# capture "title" DIR COMMAND...: adds the output of a read-only command to
# the report.
capture() {
  local title="$1" dir="$2"; shift 2
  {
    printf '\n<details><summary>%s</summary>\n\n```\n' "$title"
    (cd "$dir" && "$@" 2>&1) || true
    printf '```\n\n</details>\n\n'
  } >> "$LOG"
}

# Read-only predicates for check.
git_new_enough() { git version | awk '{split($3, v, "."); exit !(v[1] > 2 || (v[1] == 2 && v[2] >= 38))}'; }
gh_is_maintainer() { [[ "$(gh api user --jq .login 2>/dev/null)" == "admSla99" ]]; }
has_ref() { git -C "$1" rev-parse --verify --quiet "$REF" >/dev/null; }
remote_tip() {
  local out
  out=$(git ls-remote "$REPO_URL" "$REF") || return 1
  cut -f1 <<<"$out"
}
same_as_remote() {
  local ours theirs
  ours=$(git -C "$1" rev-parse --verify --quiet "$REF") || return 1
  theirs=$(remote_tip) || return 1
  [[ -n "$theirs" && "$ours" == "$theirs" ]]
}
# show_has DIR ID TEXT: bfc show ID in DIR prints TEXT.
show_has() {
  local out
  out=$(cd "$1" && bfc show "$2" 2>&1) || return 1
  grep -qF -- "$3" <<<"$out"
}
# has_close: bfc lists the close command (#49). "bfc close --help" is no
# test: for an unknown command cobra prints the main help and exits 0.
has_close() {
  local out
  out=$(bfc --help 2>&1) || return 1
  grep -qE '^  close ' <<<"$out"
}
# untouched DIR: on main at the cloned commit, nothing changed or added in
# the working tree. The clones are fresh, so this is the state bfc found.
untouched() {
  [[ "$(git -C "$1" symbolic-ref --short HEAD)" == "main" ]] &&
    [[ "$(git -C "$1" rev-parse HEAD)" == "$(git -C "$1" rev-parse origin/main)" ]] &&
    [[ -z "$(git -C "$1" status --porcelain --untracked-files=all)" ]]
}

# confirmed "what": asks the human whether they saw something and records
# the answer like check does.
confirmed() {
  if confirm "$1?"; then
    PASSED=$((PASSED + 1)); log "- [x] $1 (seen by hand)"
  else
    FAILED=$((FAILED + 1)); log "- [ ] $1 **(not seen)**"
  fi
}

banner "BeforeCode phase 1 on GitHub (#19 AC-5)"

{
  printf '\n## Manual run on GitHub, %s\n\n' "$(date '+%Y-%m-%d %H:%M %Z')"
  printf -- '- Repository: %s, ref `%s`\n' "$REPO_URL" "$REF"
  printf -- '- Ana: %s <%s>; Ben: %s <%s>; two clones on one machine (%s)\n' "$ANA_NAME" "$ANA_EMAIL" "$BEN_NAME" "$BEN_EMAIL" "$(uname -s)"
  printf -- '- %s; %s\n\n' "$(bfc version 2>/dev/null || echo 'bfc missing')" "$(git version)"
} >> "$LOG"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
say "Two clones on this PC play Ana (you) and Ben (a second team member)."
say "Plans go to the hidden ref $REF of the public repository."
warn "Plans there are public and are never deleted; this run closes its test plans at the end."
note "Run this once main has .beforecode/config.yaml and bfc close (#49)."
step "In your BeforeCode checkout, install bfc from an up-to-date main:"
cmd "git switch main && git pull && go install ./cmd/bfc"
step "Make sure git has an editor you like, for example:"
cmd "git config --global core.editor \"code --wait\""
pause "Press Enter when bfc is installed"
log "### Prerequisites"
check "bfc is on PATH" command -v bfc
check "git is 2.38 or newer" git_new_enough
check "gh is logged in as admSla99" gh_is_maintainer
check "main has .beforecode/config.yaml" gh api repos/admSla99/BeforeCode/contents/.beforecode/config.yaml
check "bfc has the close command (#49)" has_close
if (( FAILED > 0 )) && ! confirm "Some prerequisites failed. Continue anyway?"; then
  exit 1
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Two clones: Ana and Ben"
say "The wizard clones the repository twice into $WORK and sets each identity."
if [[ -e "$ANA" || -e "$BEN" ]]; then
  warn "$ANA or $BEN exists from an earlier run."
  if confirm "Delete both clones and clone again?"; then
    rm -rf "$ANA" "$BEN"
  fi
fi
for dir in "$ANA" "$BEN"; do
  [[ -e "$dir" ]] || git clone -q "$REPO_URL" "$dir"
done
git -C "$ANA" config user.name "$ANA_NAME"
git -C "$ANA" config user.email "$ANA_EMAIL"
git -C "$BEN" config user.name "$BEN_NAME"
git -C "$BEN" config user.email "$BEN_EMAIL"
log "" "### Setup"
check "Ana's clone is on main and clean" untouched "$ANA"
check "Ben's clone is on main and clean" untouched "$BEN"
step "Open two Git Bash windows and go to the clones:"
in_window Ana "$ANA"; cmd "cd \"$ANA\""
in_window Ben "$BEN"; cmd "cd \"$BEN\""
pause "Press Enter when both windows are ready"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Ana: set up BeforeCode"
in_window Ana "$ANA"
if ! tip=$(remote_tip); then
  warn "GitHub cannot be asked for $REF: check the network and git ls-remote $REPO_URL."
  exit 1
fi
log "" "### Ana sets up BeforeCode"
if [[ -n "$tip" ]]; then
  note "GitHub already has $REF (an earlier run), so Ana joins with bootstrap."
  note "This run does not test bfc init."
  log "- GitHub already had $REF, so Ana ran bfc bootstrap; bfc init was not tested in this run."
  cmd "bfc bootstrap"
else
  cmd "bfc init"
  note "init keeps config.yaml and the templates from main and creates the plans ref."
  log "- Ana ran bfc init on a repository without $REF."
fi
cmd "bfc doctor"
note "Before the first push, doctor fails 'remote: origin has no ... yet' with the fix bfc push. That is expected."
pause "Press Enter when done"
check "Ana has the plans ref" has_ref "$ANA"
check "Ana's checkout is untouched" untouched "$ANA"
capture "Ana: bfc doctor before the first push" "$ANA" bfc doctor

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Ana: write, submit and push a plan"
TITLE1="E2E $STAMP: payments via Stripe"
in_window Ana "$ANA"
cmd "bfc new \"$TITLE1\""
note "Your editor opens intent.md. Write a sentence under ## Problem, save and close."
cmd "bfc list"
ask SHORT1 "Short ID of \"$TITLE1\" (bfc-xxxx):"
write_env SHORT1 "$SHORT1"
cmd "bfc edit $SHORT1"
say "Replace the template in the editor with this plan.md, then save and close:"
printf '%s' "$DIM"
cat <<'PLAN'
      ## Context
      Card payments fail for some EU customers.
      ## Approach
      Move checkout to Stripe Payment Intents.
      ## Affected areas
      The checkout service.
      ## Out of scope
      Refunds.
      ## Tasks
      - Replace the charge call.
      ## Acceptance criteria
      - AC-1: A card that needs 3-D Secure completes checkout.
PLAN
printf '%s' "$RESET"
note "Write the lines without the leading spaces."
cmd "bfc submit $SHORT1"
cmd "bfc push"
pause "Press Enter when pushed"
log "" "### Ana writes and submits"
check "$SHORT1 is in review for Ana" show_has "$ANA" "$SHORT1" "State:      in-review"
check "GitHub has Ana's plans ref" same_as_remote "$ANA"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Ben: join"
in_window Ben "$BEN"
cmd "bfc bootstrap"
cmd "bfc show $SHORT1"
pause "Press Enter when done"
log "" "### Ben joins"
check "Ben has the remote's plans ref" same_as_remote "$BEN"
check "Ben sees $SHORT1 in review" show_has "$BEN" "$SHORT1" "State:      in-review"
check "Ben sees the acceptance criterion" show_has "$BEN" "$SHORT1" "AC-1: A card that needs 3-D Secure"
check "Ben's checkout is untouched" untouched "$BEN"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Ben: approve"
in_window Ben "$BEN"
cmd "bfc approve $SHORT1"
cmd "bfc push"
pause "Press Enter when pushed"
log "" "### Ben approves"
check "Ben sees $SHORT1 approved" show_has "$BEN" "$SHORT1" "State:      approved"
check "GitHub has Ben's approval" same_as_remote "$BEN"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Ana: sees the approval"
in_window Ana "$ANA"
cmd "bfc pull"
cmd "bfc show $SHORT1"
pause "Press Enter when done"
log "" "### Ana sees the approval"
check "Ana sees $SHORT1 approved" show_has "$ANA" "$SHORT1" "State:      approved"
check "approved by Ben" show_has "$ANA" "$SHORT1" "Approvals:  1/1 ($BEN_EMAIL)"
capture "Ana: bfc show $SHORT1" "$ANA" bfc show "$SHORT1"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Concurrent writes"
TITLE2="E2E $STAMP: search by customer email"
say "Both write before either pushes."
in_window Ana "$ANA"
cmd "bfc edit --intent $SHORT1"
note "Add the line 'Concurrent edit by Ana.' at the end, save and close. Do not push yet."
in_window Ben "$BEN"
cmd "bfc new --no-edit \"$TITLE2\""
pause "Press Enter when both have written"
in_window Ana "$ANA"; cmd "bfc push"
pause "Press Enter when Ana has pushed"
in_window Ben "$BEN"; cmd "bfc push"
note "Ben's push is rejected first; bfc merges Ana's change and pushes again."
log "" "### Concurrent writes"
confirmed "Ben's push said 'after merging changes pushed meanwhile'"
in_window Ana "$ANA"; cmd "bfc pull"
in_window Ben "$BEN"; cmd "bfc list"
ask SHORT2 "Short ID of \"$TITLE2\" (bfc-xxxx):"
write_env SHORT2 "$SHORT2"
check "Ana and GitHub agree" same_as_remote "$ANA"
check "Ben and GitHub agree" same_as_remote "$BEN"
check "Ben has Ana's intent edit" show_has "$BEN" "$SHORT1" "Concurrent edit by Ana."
check "Ana has Ben's new plan" show_has "$ANA" "$SHORT2" "$TITLE2"
capture "Ben: bfc list" "$BEN" bfc list

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Checkouts and the TUI"
log "" "### Checkouts"
check "Ana's checkout is untouched" untouched "$ANA"
check "Ben's checkout is untouched" untouched "$BEN"
say "Optional: look at the plans in the TUI, which syncs in the background."
in_window Ana "$ANA"; cmd "bfc"
note "Enter opens a plan, Tab switches documents, Esc goes back, q quits."
pause "Press Enter to continue"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Clean up: close the test plans"
log "" "### Clean up"
if has_close; then
  in_window Ana "$ANA"
  cmd "bfc close $SHORT1 -m \"End-to-end test of phase 1 (#19)\""
  cmd "bfc close $SHORT2 -m \"End-to-end test of phase 1 (#19)\""
  cmd "bfc push"
  in_window Ben "$BEN"
  cmd "bfc pull"
  cmd "bfc doctor"
  pause "Press Enter when done"
  check "$SHORT1 is closed" show_has "$BEN" "$SHORT1" "State:      closed"
  check "$SHORT2 is closed" show_has "$BEN" "$SHORT2" "State:      closed"
  check "Ben and GitHub agree" same_as_remote "$BEN"
  capture "Ben: bfc doctor" "$BEN" bfc doctor
else
  warn "bfc close is not available yet (#49), so the test plans stay open."
  SKIPPED+=("close $SHORT1 and $SHORT2 with bfc close once #49 is merged")
  log "- [ ] closing the test plans: bfc close is not available yet (#49)"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Result"
log "" "**Result: $PASSED checks passed, $FAILED failed.**"
if (( FAILED == 0 )); then
  printf '  %s✓ all %s checks passed%s\n' "$GREEN" "$PASSED" "$RESET"
else
  printf '  %s✗ %s of %s checks failed%s\n' "$RED" "$FAILED" "$((PASSED + FAILED))" "$RESET"
fi
say "The report is in $LOG."
step "Paste it into the pull request for #19, or attach it."
pause "Press Enter to finish"

finish
